function topic(
  slug: string, title: string, summary: string, introduction: string,
  factors: string[], signs: string[], impact: string, prevention: string[],
  firstSteps: string[], seekHelp: string,
  faqs: [string, string][], sources: Reference[],
): Topic {
  return {
    slug, title, summary, introduction, factors, signs, impact, prevention,
    firstSteps, seekHelp,
    faqs: faqs.map(([question, answer]) => ({ question, answer })),
    sources, checkedAt: reviewed,
  };
}

export const healthTopics: Topic[] = [
  topic("kesehatan-reproduksi", "Kesehatan reproduksi remaja", "Memahami tubuh, relasi yang saling menghormati, dan cara menjaga kesehatan reproduksi.", "Kesehatan reproduksi mencakup keadaan fisik, mental, dan sosial yang berkaitan dengan sistem serta fungsi reproduksi. Memahami informasi yang tepat membantu remaja menjaga diri dan mengetahui kapan perlu bertanya kepada tenaga kesehatan.", ["Perubahan pubertas dan informasi yang belum dipahami", "Tekanan teman sebaya atau informasi daring yang tidak terverifikasi", "Kesulitan mengakses orang dewasa atau tenaga kesehatan tepercaya"], ["Pertanyaan tentang perubahan tubuh, batas pribadi, atau relasi", "Kebingungan setelah membaca informasi yang berbeda-beda", "Rasa tidak nyaman atau keluhan pada tubuh yang menetap"], "Informasi yang tidak tepat dapat membuat seseorang menunda perawatan atau merasa takut bertanya. Setiap orang berhak memperoleh informasi kesehatan yang sesuai usia dan menghormati martabatnya.", ["Gunakan sumber kesehatan resmi dan tenaga kesehatan berkompeten", "Kenali batas tubuh dan hormati persetujuan serta batas orang lain", "Bicarakan pertanyaan dengan orang dewasa yang aman atau petugas kesehatan"], ["Tuliskan pertanyaan umum untuk dibawa saat konsultasi; jangan kirim identitas melalui situs ini", "Hindari mencoba obat atau tindakan berdasarkan unggahan media sosial", "Cari layanan kesehatan yang jelas kewenangan dan privasinya"], "Cari bantuan tenaga kesehatan bila ada keluhan fisik, kekhawatiran, atau pengalaman yang membuatmu tidak aman. Untuk kekerasan, utamakan tempat aman dan hubungi orang dewasa tepercaya atau SAPA 129.", [["Apakah wajar merasa malu bertanya?", "Ya, banyak orang merasa sungkan. Kamu boleh menyiapkan pertanyaan tertulis dan meminta penjelasan dengan bahasa yang mudah dipahami."], ["Apakah SIRAMA dapat memberi diagnosis?", "Tidak. Halaman ini untuk edukasi umum dan tidak menggantikan pemeriksaan atau nasihat tenaga kesehatan."], ["Ke mana bertanya tentang kesehatan reproduksi?", "Kamu dapat bertanya kepada tenaga kesehatan di fasilitas yang berwenang. Pastikan informasi layanan dan privasinya terlebih dahulu."]], [kemenkesRepro, kemenkesPuberty]),
  topic("pubertas", "Pubertas dan perubahan fisik", "Mengenali perubahan pubertas tanpa membandingkan tubuhmu dengan orang lain.", "Pubertas adalah masa ketika tubuh berkembang menuju kematangan reproduksi. Waktu mulai dan urutan perubahan bisa berbeda pada tiap orang; perbedaan itu tidak otomatis berarti ada masalah.", ["Faktor keturunan dan perkembangan individu", "Kondisi kesehatan dan gizi dapat berpengaruh terhadap perkembangan", "Membandingkan diri dengan teman atau konten daring"], ["Pertumbuhan tinggi dan perubahan bentuk tubuh", "Perubahan suara, kulit, rambut tubuh, atau menstruasi", "Perubahan emosi dan kebutuhan akan ruang pribadi"], "Perubahan yang tidak dipahami dapat menimbulkan cemas atau rasa tidak percaya diri. Informasi yang tenang dan terpercaya membantu remaja mengenali tubuh tanpa stigma.", ["Pahami bahwa ritme perkembangan setiap orang berbeda", "Jaga kebersihan diri dan kebiasaan hidup sehat", "Bicarakan kekhawatiran dengan orang dewasa aman atau tenaga kesehatan"], ["Cari informasi dari sumber kesehatan resmi", "Catat perubahan atau keluhan yang ingin ditanyakan", "Jangan mencoba suplemen atau obat untuk mengubah pubertas tanpa arahan tenaga kesehatan"], "Konsultasikan dengan tenaga kesehatan jika perubahan tubuh atau keluhan membuatmu khawatir, terasa mengganggu, atau membutuhkan pemeriksaan.", [["Apakah semua remaja mengalami pubertas pada waktu yang sama?", "Tidak. Waktu dan urutan perubahan berbeda. Tenaga kesehatan dapat membantu menilai kekhawatiran berdasarkan kondisi masing-masing."], ["Apakah perubahan emosi saat pubertas selalu berarti gangguan?", "Tidak. Emosi dapat berubah karena banyak hal. Jika perubahan terasa berat atau mengganggu keseharian, bicarakan dengan orang tepercaya atau profesional."], ["Bolehkah memakai obat untuk mempercepat atau menunda pubertas?", "Jangan memakai obat atau hormon tanpa pemeriksaan dan arahan tenaga kesehatan."]], [kemenkesPuberty, kemenkesRepro]),
  topic("kebersihan-diri", "Kebersihan diri dan organ reproduksi", "Kebiasaan sederhana untuk menjaga kenyamanan dan kebersihan tubuh.", "Kebersihan diri merupakan bagian dari perawatan kesehatan sehari-hari. Saat pubertas, perubahan keringat dan tubuh dapat membuat rutinitas kebersihan terasa berbeda.", ["Kebiasaan perawatan diri yang belum terbentuk", "Keterbatasan akses terhadap air bersih atau perlengkapan kebersihan", "Informasi yang menyarankan produk berpewangi atau tindakan yang tidak diperlukan"], ["Bau badan atau rasa tidak nyaman setelah aktivitas", "Iritasi atau keluhan yang berulang", "Kebingungan memilih cara merawat organ reproduksi"], "Mengabaikan kebersihan atau menggunakan produk yang mengiritasi dapat membuat tubuh tidak nyaman. Keluhan berulang sebaiknya dibicarakan dengan tenaga kesehatan.", ["Mandi dan ganti pakaian dalam secara teratur sesuai kebutuhan", "Bersihkan area luar tubuh dengan lembut; hindari pewangi dan pembersih keras", "Gunakan pakaian bersih dan kering serta jangan berbagi barang pribadi"], ["Hentikan produk yang terasa menyebabkan iritasi", "Jaga area tetap bersih dan kering", "Tanyakan kepada tenaga kesehatan sebelum memakai obat atau produk khusus"], "Mintalah pemeriksaan tenaga kesehatan bila ada nyeri, luka, gatal berat, cairan yang tidak biasa, atau keluhan yang berulang.", [["Apakah perlu memakai sabun berpewangi di area intim?", "Tidak perlu menggunakan pewangi atau pembersih keras. Ikuti anjuran tenaga kesehatan bila ada keluhan."], ["Apakah keluhan gatal pasti infeksi?", "Tidak dapat dipastikan dari satu gejala. Penyebabnya beragam dan perlu dinilai tenaga kesehatan bila menetap."], ["Apa yang dilakukan bila suatu produk menimbulkan iritasi?", "Hentikan pemakaian produk tersebut dan cari saran tenaga kesehatan jika iritasi berlanjut."]], [kemenkesHygiene, kemenkesRepro]),
  topic("menstruasi", "Menstruasi", "Informasi dasar tentang siklus menstruasi, kebersihan, dan kapan perlu memeriksakan diri.", "Menstruasi merupakan bagian dari siklus reproduksi. Pola dapat berbeda pada masa awal menstruasi, tetapi keluhan yang berat atau mengganggu tetap layak dibicarakan dengan tenaga kesehatan.", ["Perubahan hormon dan tahap perkembangan", "Stres, kondisi kesehatan, dan perubahan rutinitas dapat berpengaruh pada siklus", "Informasi keliru atau rasa malu untuk meminta perlengkapan"], ["Perdarahan berkala dan kram pada sebagian orang", "Perubahan suasana hati atau energi yang bervariasi", "Perubahan pola yang terasa berbeda dari biasanya"], "Kurangnya informasi atau akses perlengkapan dapat mengganggu kegiatan sekolah dan rasa nyaman. Menstruasi bukan sesuatu yang perlu dipermalukan.", ["Catat tanggal dan keluhan bila itu membantu memahami pola", "Ganti pembalut secara berkala sesuai kebutuhan dan cuci tangan", "Siapkan perlengkapan menstruasi dan minta bantuan bila akses terbatas"], ["Beristirahat dan minum cukup sesuai kebutuhan", "Gunakan cara nyaman yang aman; jangan minum obat tanpa membaca petunjuk atau saran tenaga kesehatan", "Bicarakan keluhan dengan orang dewasa tepercaya atau tenaga kesehatan"], "Segera cari bantuan medis bila perdarahan sangat banyak, nyeri berat, pingsan, atau ada kondisi yang terasa darurat. Untuk pola yang terus mengganggu, jadwalkan konsultasi tenaga kesehatan.", [["Apakah siklus yang belum teratur selalu berbahaya?", "Tidak selalu, terutama pada masa awal. Namun perubahan menetap atau keluhan yang mengganggu sebaiknya dinilai tenaga kesehatan."], ["Bagaimana menjaga kebersihan saat menstruasi?", "Ganti pembalut sesuai kebutuhan, cuci tangan sebelum dan sesudah, dan buang pembalut dengan cara yang menjaga kebersihan."], ["Kapan nyeri menstruasi perlu dibicarakan dengan petugas?", "Jika nyeri berat, mengganggu sekolah atau kegiatan, atau disertai keluhan lain, mintalah pemeriksaan."]], [kemenkesHygiene, kemenkesRepro, kemenkesMenstruation]),
  topic("gizi-seimbang", "Pola makan dan gizi seimbang", "Membangun kebiasaan makan beragam tanpa diet ekstrem atau rasa bersalah terhadap makanan.", "Masa remaja melibatkan pertumbuhan dan kebutuhan gizi. Pedoman Isi Piringku Kementerian Kesehatan mendorong variasi makanan dan keseimbangan porsi, bukan satu jenis makanan yang dianggap ajaib.", ["Jadwal sekolah dan aktivitas yang padat", "Akses dan kebiasaan keluarga", "Tekanan citra tubuh dan informasi diet dari media sosial"], ["Melewatkan makan karena jadwal atau aturan diet", "Kebingungan memilih makanan karena banyak saran yang bertentangan", "Perubahan energi atau kebugaran yang perlu dinilai secara menyeluruh"], "Pola makan yang terlalu membatasi dapat menyulitkan pemenuhan kebutuhan tubuh. Perubahan energi tidak cukup untuk menyimpulkan kondisi gizi atau penyakit.", ["Usahakan makanan beragam sesuai akses dan kebiasaan keluarga", "Ikuti pedoman gizi seimbang, minum air, dan bergerak sesuai kemampuan", "Hindari diet ekstrem, produk pelangsing, atau suplemen tanpa arahan ahli"], ["Mulai dengan satu kebiasaan yang realistis, misalnya sarapan atau menambah variasi", "Jika ada kesulitan makan, bicarakan dengan orang dewasa aman atau tenaga kesehatan", "Jangan gunakan informasi ini untuk mendiagnosis kekurangan gizi"], "Bicarakan dengan tenaga kesehatan atau ahli gizi bila perubahan makan, berat badan, atau energi mengganggu kesehatan atau kegiatan sehari-hari.", [["Apakah ada satu menu yang cocok untuk semua remaja?", "Tidak. Kebutuhan dan akses berbeda. Pedoman umum membantu, tetapi tenaga kesehatan dapat memberi saran yang sesuai kondisi seseorang."], ["Apakah saya perlu menghindari semua makanan tertentu?", "Tidak ada larangan umum yang berlaku untuk semua orang. Hindari aturan ekstrem dan tanyakan kepada tenaga kesehatan bila ada kondisi khusus."], ["Apakah suplemen selalu diperlukan?", "Tidak. Suplemen perlu digunakan sesuai kebutuhan dan arahan tenaga kesehatan."]], [kemenkesNutrition, kemenkesRepro]),
  topic("anemia", "Anemia pada remaja", "Mengenali kemungkinan tanda anemia dan pentingnya pemeriksaan, bukan menebak diagnosis sendiri.", "Anemia adalah kondisi yang perlu dinilai melalui pemeriksaan. Kementerian Kesehatan menyebut rasa lelah, lemah, pucat, pusing, atau sulit berkonsentrasi sebagai gejala yang dapat muncul; tanda tersebut juga dapat memiliki penyebab lain.", ["Kebutuhan zat besi meningkat selama pertumbuhan", "Asupan zat besi yang tidak mencukupi", "Menstruasi dapat menjadi salah satu faktor yang perlu dinilai tenaga kesehatan"], ["Lelah atau lemah", "Pucat, pusing, atau sulit berkonsentrasi", "Keluhan lain yang menetap atau mengganggu aktivitas"], "Bila tidak dikenali, keluhan anemia dapat memengaruhi kebugaran dan kegiatan harian. Gejala saja tidak cukup untuk memastikan anemia.", ["Konsumsi makanan beragam sesuai pedoman gizi seimbang", "Ikuti program skrining dan suplementasi dari tenaga kesehatan atau sekolah", "Jangan mengonsumsi tablet tambah darah sebagai pengganti pemeriksaan bila ada keluhan"], ["Ceritakan keluhan kepada orang dewasa tepercaya", "Minta penilaian di fasilitas kesehatan, terutama jika keluhan berulang", "Gunakan suplemen hanya sesuai petunjuk tenaga kesehatan atau program resmi"], "Cari penilaian tenaga kesehatan jika lelah, pucat, pusing, atau sulit berkonsentrasi berlangsung atau mengganggu kegiatan. Kondisi berat atau pingsan perlu pertolongan segera.", [["Apakah lelah berarti saya anemia?", "Belum tentu. Lelah punya banyak penyebab dan anemia perlu dipastikan melalui penilaian atau pemeriksaan."], ["Bolehkah minum tablet tambah darah sendiri?", "Ikuti petunjuk tenaga kesehatan atau program resmi. Jangan menggandakan dosis atau memakai suplemen tanpa arahan."], ["Ke mana saya bisa melakukan skrining?", "Tanyakan fasilitas kesehatan atau petugas kesehatan sekolah yang berwenang tentang layanan skrining yang tersedia."]], [kemenkesAnemia, kemenkesRepro]),
  topic("kesehatan-seksual-reproduksi", "Kesehatan seksual dan reproduksi", "Belajar tentang batas diri, relasi sehat, dan informasi reproduksi yang sesuai usia.", "Informasi kesehatan seksual dan reproduksi yang sesuai usia membantu remaja memahami tubuh, risiko, perlindungan diri, serta hak untuk mendapat layanan yang menghormati martabat.", ["Informasi yang tidak sesuai atau tidak dapat diverifikasi", "Tekanan relasi, teman sebaya, atau media", "Sulit berbicara dengan orang dewasa atau tenaga kesehatan tepercaya"], ["Pertanyaan tentang persetujuan, batas pribadi, atau kesehatan tubuh", "Kekhawatiran setelah mengalami tekanan atau sentuhan yang tidak diinginkan", "Keluhan fisik yang membuat tidak nyaman"], "Informasi yang keliru dapat meningkatkan risiko kesehatan dan membuat seseorang sulit mencari pertolongan. Tidak ada seorang pun yang berhak memaksa atau menyentuh tubuhmu tanpa persetujuan.", ["Pelajari tubuh dan perlindungan diri dari sumber kesehatan resmi", "Bangun relasi yang menghormati batas, persetujuan, dan keselamatan", "Cari layanan kesehatan yang sesuai dan berkompeten bila ada pertanyaan"], ["Jika merasa ditekan atau tidak aman, pindah ke tempat yang aman dan hubungi orang dewasa tepercaya", "Jangan menghadapi orang yang membuatmu takut sendirian jika ada risiko", "Untuk kekerasan pada anak/perempuan, kanal resmi SAPA 129 tersedia"], "Untuk keluhan kesehatan, cari tenaga kesehatan. Jika ada pemaksaan, pelecehan, atau kekerasan, utamakan keselamatan dan hubungi orang dewasa aman atau SAPA 129.", [["Apa yang dimaksud persetujuan?", "Persetujuan harus diberikan secara bebas, tanpa tekanan, dan dapat ditarik. Jika kamu merasa dipaksa atau takut, cari bantuan orang dewasa aman."], ["Apakah SIRAMA memberi nasihat klinis?", "Tidak. SIRAMA menyediakan edukasi umum dan tautan ke sumber resmi."], ["Apa yang harus dilakukan jika batas tubuh dilanggar?", "Pergi ke tempat aman bila memungkinkan, hubungi orang yang dipercaya, dan cari bantuan layanan perlindungan atau kesehatan."]], [kemenkesRepro, sapa]),
  topic("pencegahan-ims", "Pencegahan infeksi menular seksual", "Informasi netral tentang pencegahan, pemeriksaan, dan layanan kesehatan yang menjaga privasi.", "Infeksi menular seksual (IMS) merupakan kelompok infeksi yang perlu dicegah dan ditangani oleh tenaga kesehatan. Informasi online tidak dapat memastikan ada atau tidaknya infeksi.", ["Kontak seksual tanpa perlindungan", "Tidak melakukan pemeriksaan saat ada pajanan atau keluhan", "Stigma atau hambatan untuk mengakses layanan"], ["Sebagian IMS dapat tidak menimbulkan gejala yang jelas", "Keluhan dapat berupa perubahan pada area genital atau nyeri, tetapi tandanya tidak spesifik", "Hanya pemeriksaan tenaga kesehatan dapat menilai kondisi"], "IMS yang tidak ditangani dapat menimbulkan dampak kesehatan. Penilaian lebih awal membantu seseorang mendapatkan informasi dan perawatan yang sesuai.", ["Pelajari pencegahan dari tenaga kesehatan dan sumber resmi", "Hindari berbagi alat suntik atau benda yang dapat membawa darah", "Jika merasa berisiko, cari layanan kesehatan untuk informasi pencegahan dan pemeriksaan"], ["Jangan mencoba mendiagnosis dari foto atau daftar gejala internet", "Jangan memakai antibiotik atau obat orang lain", "Cari layanan kesehatan yang menjaga privasi dan menjelaskan pilihan pemeriksaan"], "Konsultasikan dengan tenaga kesehatan setelah kemungkinan pajanan atau bila ada keluhan. Penanganan dini dan pemeriksaan profesional lebih aman daripada menunda atau mengobati sendiri.", [["Apakah IMS selalu memiliki gejala?", "Tidak. Sebagian infeksi dapat tidak menunjukkan gejala. Pemeriksaan tenaga kesehatan diperlukan bila ada kemungkinan pajanan."], ["Apakah saya bisa memastikan IMS dari gejala?", "Tidak. Gejala dapat serupa dengan kondisi lain dan pemeriksaan profesional diperlukan."], ["Bolehkah memakai obat yang tersisa?", "Tidak dianjurkan. Obat yang tidak sesuai dapat tidak efektif dan berisiko; mintalah saran tenaga kesehatan."]], [kemenkesHiv, kemenkesRepro]),
  topic("pencegahan-pernikahan-anak", "Pencegahan pernikahan anak", "Mengenali pentingnya perlindungan, pendidikan, dukungan keluarga, dan akses konsultasi yang aman.", "Keputusan menikah pada usia anak berkaitan dengan perlindungan, pendidikan, kesehatan, dan kesejahteraan. SIRAMA tidak memberi nasihat hukum individual; keluarga dapat mencari penjelasan dari layanan perlindungan anak dan instansi berwenang.", ["Tekanan keluarga atau lingkungan", "Kehamilan atau kondisi sosial yang sulit", "Keterbatasan akses terhadap pendidikan dan dukungan"], ["Pembicaraan tentang pernikahan yang disertai tekanan atau ancaman", "Khawatir kehilangan akses sekolah atau dukungan keluarga", "Merasa tidak memiliki ruang untuk menyampaikan pendapat"], "Keputusan yang diambil di bawah paksaan dapat berdampak terhadap keselamatan, kesehatan, pendidikan, dan kesejahteraan. Anak perlu mendapat perlindungan dan dukungan orang dewasa yang aman.", ["Bangun komunikasi dengan orang dewasa tepercaya yang mengutamakan keselamatan", "Cari konseling dan informasi dari layanan perlindungan anak yang berwenang", "Jaga kesinambungan akses pendidikan dan dukungan sosial bila memungkinkan"], ["Jika ada ancaman, jangan berhadapan sendiri dengan pihak yang menekan", "Hubungi orang dewasa aman, guru BK, pekerja sosial, atau layanan perlindungan", "SAPA 129 menyediakan kanal bantuan untuk kekerasan terhadap anak dan perempuan"], "Jika ada paksaan, ancaman, atau bahaya, cari tempat aman dan hubungi orang dewasa tepercaya atau SAPA 129. Untuk pertanyaan hukum, minta pendampingan dari instansi berwenang.", [["Apa yang bisa dilakukan jika saya ditekan untuk menikah?", "Ceritakan kepada orang dewasa yang aman dan minta bantuan layanan perlindungan anak. Jika ada ancaman, prioritaskan tempat aman."], ["Apakah SIRAMA dapat memberi keputusan hukum?", "Tidak. Untuk penjelasan hukum dan layanan resmi, hubungi instansi atau pendamping yang berwenang."], ["Bagaimana jika saya khawatir pendidikan terhenti?", "Bicarakan dengan guru atau layanan pendidikan yang kamu percaya untuk mencari pilihan dukungan."]], [sapa, kemenkesRepro, kemendukbanggaMarriage]),
  topic("perilaku-hidup-bersih-sehat", "Perilaku hidup bersih dan sehat", "Kebiasaan harian yang mendukung kebersihan, gizi, aktivitas, dan kesehatan remaja.", "Perilaku hidup bersih dan sehat (PHBS) mencakup kebiasaan yang mendukung kesehatan diri dan lingkungan. Langkah yang realistis dan dapat dilakukan bersama lebih mudah dijaga daripada perubahan ekstrem.", ["Akses sarana kebersihan dan air bersih", "Rutinitas sekolah, rumah, dan lingkungan", "Informasi kesehatan yang saling bertentangan"], ["Kebiasaan cuci tangan atau kebersihan yang belum konsisten", "Pola makan, tidur, atau aktivitas yang terasa kurang seimbang", "Kesulitan menjaga rutinitas karena lingkungan atau beban kegiatan"], "Kebiasaan yang mendukung kesehatan membantu kenyamanan dan kesejahteraan sehari-hari. Keterbatasan fasilitas bukan kesalahan individu dan membutuhkan dukungan lingkungan.", ["Cuci tangan dengan sabun pada waktu penting", "Pilih makanan beragam dan bergerak secara teratur sesuai kemampuan", "Jaga kebersihan diri serta ruang bersama dengan dukungan keluarga/sekolah"], ["Pilih satu kebiasaan kecil untuk mulai diperbaiki", "Minta dukungan keluarga atau sekolah bila fasilitas menjadi hambatan", "Gunakan panduan Kementerian Kesehatan untuk informasi gizi"], "Untuk keluhan kesehatan yang menetap, konsultasikan dengan tenaga kesehatan. Jika hambatan utamanya fasilitas lingkungan, sampaikan kepada pihak sekolah atau pengelola setempat.", [["Haruskah semua kebiasaan sehat dilakukan sekaligus?", "Tidak. Mulai dari kebiasaan yang paling mungkin dilakukan dan tambahkan langkah lain secara bertahap."], ["Apakah kebersihan sepenuhnya tanggung jawab remaja?", "Tidak. Lingkungan, fasilitas, keluarga, dan sekolah juga berperan menyediakan dukungan."], ["Apakah pola hidup sehat dapat menggantikan perawatan medis?", "Tidak. Kebiasaan sehat mendukung kesejahteraan, tetapi tidak menggantikan diagnosis atau perawatan tenaga kesehatan."]], [kemenkesNutrition, kemenkesHygiene, kemenkesPhbs]),
];

export const mentalTopics: Topic[] = [
  topic("stres-remaja", "Stres pada remaja", "Memahami respons terhadap tekanan dan menemukan langkah kecil untuk kembali merasa tertata.", "Stres adalah respons terhadap tuntutan atau perubahan. Sedikit tekanan dapat dirasakan sebelum tantangan, tetapi stres yang berkepanjangan dan mengganggu keseharian perlu mendapat perhatian.", ["Tugas sekolah dan target akademik", "Konflik keluarga atau relasi", "Perubahan, ketidakpastian, dan kurang waktu istirahat"], ["Pikiran terus memikirkan masalah", "Mudah lelah, sulit fokus, atau perubahan tidur", "Lebih mudah tersinggung atau menarik diri"], "Stres yang terus berlangsung dapat memengaruhi tidur, belajar, relasi, dan kesehatan. Tanda ini bukan diagnosis dan setiap orang dapat mengalaminya berbeda.", ["Bagi tugas menjadi langkah kecil dan realistis", "Jaga rutinitas istirahat, makan, dan aktivitas", "Berbagi dengan orang yang aman dan tidak menghakimi"], ["Berhenti sejenak dan pilih satu hal yang dapat dilakukan sekarang", "Gunakan latihan napas atau grounding bila terasa membantu", "Kurangi sumber tekanan yang dapat diatur dan minta bantuan untuk yang sulit"], "Cari bantuan profesional bila stres berlangsung lama, terasa berat, mengganggu fungsi harian, atau sulit diatasi sendiri.", [["Apa bedanya stres biasa dan stres yang perlu bantuan?", "Lihat durasi, intensitas, dan dampaknya pada keseharian. Bila tidur, belajar, relasi, atau keselamatan terganggu, bicarakan dengan profesional."], ["Bagaimana mengelola stres akademik?", "Pecah tugas, buat jeda realistis, minta bantuan guru, dan prioritaskan istirahat yang cukup."], ["Apakah saya harus menyelesaikan semua sendiri?", "Tidak. Meminta bantuan orang tepercaya atau profesional merupakan langkah yang wajar."]], [whoMental, healing]),
  topic("kecemasan", "Kecemasan", "Mengenali rasa khawatir dan kapan dukungan profesional dapat membantu.", "Kecemasan adalah pengalaman khawatir atau takut yang dapat muncul dalam berbagai situasi. Hanya tenaga profesional yang dapat menilai apakah gejala berkaitan dengan kondisi tertentu.", ["Tekanan, perubahan, pengalaman sulit, atau masalah relasi", "Kurang istirahat dan beban yang menumpuk", "Faktor biologis dan lingkungan yang berbeda bagi tiap orang"], ["Khawatir yang sulit dihentikan", "Gelisah, sulit berkonsentrasi, atau gangguan tidur", "Menghindari kegiatan karena takut atau cemas"], "Kecemasan dapat memengaruhi kegiatan sehari-hari, tetapi tidak berarti seseorang lemah atau gagal. Pengalaman dan kebutuhan bantuan setiap orang berbeda.", ["Kenali pemicu tanpa menyalahkan diri", "Jaga rutinitas dan bicara dengan orang yang aman", "Cari informasi dari profesional, bukan diagnosis mandiri dari kuis internet"], ["Coba tarik napas perlahan atau grounding jika terasa membantu", "Ambil langkah kecil menuju kegiatan yang dihindari, tanpa memaksakan diri", "Buat janji dengan konselor/tenaga kesehatan bila dampaknya berulang"], "Cari bantuan profesional bila kecemasan mengganggu sekolah, tidur, relasi, atau aktivitas yang penting bagimu.", [["Apakah sering cemas berarti saya memiliki gangguan?", "Tidak dapat disimpulkan dari satu tanda. Penilaian hanya dapat dilakukan oleh profesional."], ["Apa yang bisa dilakukan saat rasa cemas muncul?", "Pindah ke tempat yang terasa aman, perlambat napas, dan hubungi orang tepercaya jika kamu ingin ditemani."], ["Kapan sebaiknya berkonsultasi?", "Saat rasa cemas menetap, terasa berat, atau membatasi kehidupan sehari-hari."]], [whoMental, healing]),
  topic("tekanan-akademik", "Tekanan akademik", "Cara menghadapi target belajar tanpa mengabaikan kesehatan dan kebutuhan istirahat.", "Tekanan akademik dapat muncul dari tugas, ujian, target diri, atau harapan orang lain. Tujuan belajar penting, tetapi kesehatan dan proses belajar juga perlu dijaga.", ["Tugas menumpuk dan jadwal padat", "Target yang tidak realistis atau perbandingan dengan orang lain", "Takut mengecewakan keluarga atau guru"], ["Sulit memulai atau menyelesaikan tugas", "Tidur terganggu dan merasa kewalahan", "Kehilangan minat atau merasa harga diri hanya ditentukan nilai"], "Tekanan berkepanjangan dapat memengaruhi konsentrasi, suasana hati, dan relasi. Nilai bukan ukuran tunggal kemampuan atau nilai diri seseorang.", ["Susun prioritas dan tugas menjadi bagian yang lebih kecil", "Komunikasikan beban kepada guru, wali, atau keluarga yang mendukung", "Jadwalkan jeda dan waktu tidur yang memadai"], ["Pilih tugas paling mendesak dan kerjakan sebentar dulu", "Minta klarifikasi atau perpanjangan secara jujur bila diperlukan", "Hindari belajar semalaman sebagai kebiasaan"], "Jika tekanan terus mengganggu tidur, kesehatan, kehadiran, atau rasa aman, bicarakan dengan konselor sekolah atau profesional.", [["Bagaimana memulai tugas saat merasa kewalahan?", "Pilih satu tugas kecil, atur waktu singkat, lalu evaluasi. Minta bantuan untuk menentukan prioritas jika perlu."], ["Apakah istirahat berarti saya malas?", "Tidak. Istirahat merupakan bagian dari menjaga kemampuan belajar dan kesejahteraan."], ["Apa yang dilakukan bila takut mengecewakan orang tua?", "Cari waktu yang tenang untuk menjelaskan beban dan ajak orang dewasa tepercaya membantu percakapan."]], [whoMental]),
  topic("kepercayaan-diri", "Kepercayaan diri dan penerimaan diri", "Mengembangkan pandangan yang lebih adil terhadap diri dan proses bertumbuh.", "Kepercayaan diri dapat berubah mengikuti pengalaman. Menghargai diri bukan berarti harus selalu merasa yakin; itu juga berarti memberi ruang untuk belajar dan meminta bantuan.", ["Perbandingan sosial dan komentar yang merendahkan", "Perubahan tubuh atau fase kehidupan", "Pengalaman gagal, penolakan, atau diskriminasi"], ["Sering meremehkan kemampuan diri", "Takut mencoba karena khawatir dinilai", "Menilai diri hanya dari penampilan atau pencapaian"], "Pandangan negatif yang terus menerus dapat mengurangi keberanian mencoba dan memengaruhi suasana hati. Pengalaman ini dapat dibicarakan tanpa menghakimi.", ["Kurangi paparan akun yang membuatmu merasa buruk tentang diri", "Catat usaha dan hal yang sudah dipelajari, bukan hanya hasil", "Bangun hubungan dengan orang yang menghormati batas dan pilihanmu"], ["Pilih satu langkah kecil yang sesuai minatmu", "Gunakan bahasa yang lebih adil saat menilai diri", "Bicarakan komentar atau perlakuan yang membuatmu tidak aman"], "Cari dukungan bila rasa tidak berharga menetap, mengganggu kehidupan, atau mendorong tindakan yang membahayakan diri.", [["Apakah percaya diri berarti tidak pernah ragu?", "Tidak. Ragu adalah pengalaman wajar; percaya diri juga mencakup keberanian meminta bantuan dan mencoba lagi."], ["Bagaimana berhenti membandingkan diri?", "Batasi pemicu yang tidak sehat dan ingat bahwa unggahan biasanya hanya menampilkan bagian tertentu dari hidup seseorang."], ["Apa yang dilakukan bila sering direndahkan?", "Cari orang dewasa tepercaya atau konselor. Kamu berhak diperlakukan dengan hormat."]], [whoMental, unicefCyber]),
  topic("masalah-keluarga", "Permasalahan keluarga", "Mencari cara aman untuk berbicara dan dukungan saat rumah terasa berat.", "Hubungan keluarga dapat mengalami konflik atau perubahan. Tidak semua situasi aman untuk dibicarakan langsung; keselamatan dan dukungan remaja harus menjadi pertimbangan utama.", ["Perbedaan harapan atau cara berkomunikasi", "Perubahan kondisi keluarga dan beban ekonomi", "Konflik, kontrol, atau kekerasan di rumah"], ["Merasa takut, tertekan, atau tidak didengar", "Sulit tidur atau berkonsentrasi karena konflik", "Menghindari rumah atau percakapan tertentu karena merasa tidak aman"], "Konflik berkepanjangan dapat memengaruhi kesejahteraan. Kekerasan bukan kesalahan korban dan membutuhkan dukungan dari orang atau layanan yang aman.", ["Pilih waktu bicara hanya bila situasi aman", "Minta orang dewasa tepercaya menjadi pendamping", "Kenali tempat aman yang dapat dituju bila konflik meningkat"], ["Jangan memaksakan percakapan ketika ada ancaman atau kekerasan", "Hubungi orang dewasa tepercaya, guru, atau layanan perlindungan", "Jika terancam, cari tempat aman dan bantuan segera"], "Jika ada kekerasan atau ancaman terhadap anak/perempuan, hubungi SAPA 129 atau polisi 110 saat bahaya langsung. Jangan konfrontasi pelaku sendirian.", [["Apakah semua konflik keluarga termasuk kekerasan?", "Tidak. Namun ancaman, paksaan, atau tindakan yang melukai perlu dianggap serius dan dinilai dengan bantuan pihak aman."], ["Bagaimana bila saya takut bercerita?", "Pilih orang dewasa yang tidak menghakimi, seperti guru atau kerabat yang dipercaya. Kamu dapat meminta ditemani."], ["Apa yang dilakukan jika rumah tidak aman?", "Cari tempat aman dan hubungi orang dewasa tepercaya atau layanan perlindungan."]], [whoMental, sapa]),
  topic("hubungan-pertemanan", "Hubungan pertemanan", "Membangun pertemanan yang saling menghormati dan mengenali batas yang sehat.", "Pertemanan sehat memberi ruang bagi rasa hormat, pilihan, dan batas pribadi. Perbedaan pendapat dapat terjadi, tetapi ancaman dan penghinaan berulang tidak perlu dianggap sebagai hal biasa.", ["Tekanan kelompok atau takut ditinggalkan", "Kesalahpahaman dan komunikasi yang kurang jelas", "Perundungan atau kontrol yang berulang"], ["Merasa harus selalu menurut agar diterima", "Takut menyampaikan batas atau pendapat", "Dijauhi, dipermalukan, atau diancam secara berulang"], "Relasi yang tidak sehat dapat membuat remaja cemas, menarik diri, atau merasa tidak berharga. Perlakuan merendahkan bukan ukuran nilai dirimu.", ["Sampaikan batas bila situasi aman", "Jaga pertemanan yang memberi ruang untuk berbeda", "Cari dukungan jika ada ancaman atau perundungan"], ["Ambil jarak dan cari tempat ramai/aman bila merasa terancam", "Ceritakan kepada orang dewasa tepercaya", "Simpan bukti digital jika ada cyberbullying dan gunakan fitur lapor platform"], "Jika pertemanan melibatkan kekerasan, ancaman, atau perundungan, mintalah bantuan guru, konselor, keluarga aman, atau layanan perlindungan.", [["Apakah candaan yang menyakiti termasuk perundungan?", "Dampak dan pola perilaku penting. Jika tindakan berulang, merendahkan, atau membuat seseorang tidak aman, ceritakan kepada orang dewasa tepercaya."], ["Bagaimana membantu teman yang dijauhi?", "Dengarkan, tawarkan menemani mencari bantuan, dan jangan menyebarkan cerita atau tangkapan layar."], ["Haruskah saya menghadapi teman yang mengancam?", "Tidak jika itu berisiko. Utamakan jarak aman dan minta bantuan orang dewasa."]], [whoMental, unicefCyber]),
  topic("kesepian", "Kesepian dan keterasingan", "Memahami perasaan terhubung dan mencari dukungan secara bertahap.", "Kesepian adalah perasaan kurang terhubung, bahkan ketika seseorang berada di tengah orang lain. Pengalaman ini tidak selalu terlihat oleh orang di sekitar.", ["Perubahan sekolah, lingkungan, atau hubungan", "Perasaan berbeda atau tidak diterima", "Tekanan sosial dan interaksi daring yang terasa dangkal"], ["Merasa sendirian atau tidak dipahami", "Menarik diri dari kegiatan yang biasanya disukai", "Sulit memulai percakapan atau meminta ditemani"], "Kesepian yang berlarut dapat memengaruhi suasana hati dan keterlibatan sehari-hari. Perasaan ini layak diperhatikan dan bukan tanda kelemahan.", ["Mulai dari kontak kecil dengan orang yang terasa aman", "Cari kegiatan kelompok yang sesuai minat dan batas nyaman", "Bicarakan perasaan dengan seseorang yang dipercaya"], ["Kirim pesan sederhana untuk mengajak bicara", "Pilih satu aktivitas bersama yang terasa ringan", "Jangan menilai diri berdasarkan jumlah teman atau respons media sosial"], "Cari bantuan profesional bila kesepian berlangsung lama, disertai putus asa, atau mengganggu kegiatan sehari-hari.", [["Apakah bisa merasa kesepian walau punya teman?", "Ya. Kesepian adalah pengalaman subjektif tentang keterhubungan, bukan semata jumlah teman."], ["Apa langkah kecil untuk mulai terhubung?", "Cobalah menghubungi satu orang aman atau ikut kegiatan yang kamu minati tanpa menuntut diri langsung akrab."], ["Kapan perasaan kesepian perlu bantuan profesional?", "Jika menetap, memburuk, atau mengganggu tidur, belajar, dan keseharian."]], [whoMental]),
  topic("pengelolaan-emosi", "Mengelola emosi", "Mengenali emosi dan memilih respons yang lebih aman bagi diri sendiri dan orang lain.", "Emosi memberikan informasi tentang pengalaman dan kebutuhan. Tujuan mengelola emosi bukan menekan semua perasaan, melainkan mengenalinya dan memilih respons yang aman.", ["Kurang istirahat atau tekanan yang menumpuk", "Konflik, perubahan, atau pengalaman sulit", "Belum memiliki cara yang dirasa membantu untuk menenangkan diri"], ["Emosi terasa sangat kuat atau berubah cepat", "Sulit berhenti bereaksi saat konflik", "Menyesal setelah melampiaskan emosi kepada diri sendiri atau orang lain"], "Emosi yang tidak tersalurkan secara aman dapat menambah ketegangan. Tindakan menyakiti diri/orang lain perlu segera mendapat dukungan.", ["Beri nama pada perasaan tanpa menghakimi", "Kenali hal yang membantu menenangkan diri", "Belajar menyampaikan kebutuhan dan batas dengan aman"], ["Ambil jeda dan menjauh dari situasi konflik bila aman", "Gunakan grounding, gerak ringan, atau hubungi orang tepercaya", "Jika ada risiko menyakiti diri/orang lain, jangan sendirian dan cari bantuan segera"], "Minta bantuan profesional jika emosi berulang terasa tidak terkendali atau menimbulkan risiko keselamatan.", [["Apakah menangis berarti saya tidak kuat?", "Tidak. Menangis dapat menjadi salah satu respons terhadap emosi dan tidak menentukan kekuatan seseorang."], ["Apa yang bisa dilakukan ketika emosi terasa meledak?", "Berhenti sejenak, pindah ke tempat aman, dan cari orang yang bisa menemani. Hindari keputusan saat merasa sangat tertekan."], ["Bagaimana bila saya takut menyakiti diri?", "Dekati orang yang aman sekarang, jangan sendirian, dan hubungi bantuan profesional atau layanan krisis resmi."]], [whoMental, healing]),
  topic("tekanan-media-sosial", "Tekanan media sosial", "Menjaga batas digital dan kesehatan diri di tengah arus konten serta perbandingan.", "Media sosial dapat menjadi ruang belajar dan berhubungan, sekaligus memunculkan perbandingan, tekanan, atau perundungan. Pengalaman tiap orang berbeda dan pengaturan batas dapat membantu.", ["Perbandingan dengan unggahan yang telah dikurasi", "Notifikasi dan tuntutan untuk selalu tersedia", "Komentar, pesan, atau konten yang merendahkan"], ["Suasana hati menurun setelah membuka aplikasi", "Sulit berhenti memeriksa notifikasi atau membandingkan diri", "Mengalami ancaman, penghinaan, atau penyebaran konten tanpa izin"], "Tekanan digital dapat memengaruhi suasana hati, tidur, rasa aman, dan hubungan. Cyberbullying dapat meninggalkan dampak di luar layar.", ["Atur waktu notifikasi dan akun yang diikuti", "Gunakan blokir/lapor pada platform saat ada perundungan", "Jangan membagikan data pribadi atau lokasi kepada orang yang tidak dikenal"], ["Ambil jeda dari akun/konten pemicu", "Simpan bukti perundungan digital dengan aman dan jangan menyebarkannya", "Beri tahu orang dewasa tepercaya; minta didampingi saat melapor"], "Jika ada ancaman, pemerasan, eksploitasi, atau konten intim tanpa persetujuan, jangan hadapi sendiri. Hubungi orang dewasa tepercaya dan SAPA 129.", [["Bagaimana mengurangi kebiasaan membandingkan diri?", "Kurasi akun yang diikuti, ingat bahwa unggahan bukan gambaran lengkap hidup seseorang, dan ambil jeda jika dibutuhkan."], ["Apa yang dilakukan saat di-bully online?", "Cari orang dewasa tepercaya, simpan bukti dengan aman, dan gunakan fitur blokir/lapor. Jangan membalas jika itu membahayakan."], ["Apakah saya harus menghapus akun?", "Tidak selalu. Kamu dapat mengatur privasi, membatasi notifikasi, memblokir akun, atau mengambil jeda sesuai kebutuhan."]], [whoMental, unicefCyber]),
  topic("mengenali-depresi", "Mengenali tanda depresi", "Mengenali perubahan yang menetap dan mencari penilaian profesional tanpa mendiagnosis diri.", "Depresi adalah kondisi kesehatan mental yang perlu dinilai profesional. Perasaan sedih sesekali tidak otomatis berarti depresi; perubahan yang menetap dan berdampak pada kehidupan perlu diperhatikan.", ["Pengalaman hidup, tekanan, kekerasan, atau kehilangan", "Faktor biologis, keluarga, dan lingkungan dapat berperan", "Penyebabnya tidak selalu sederhana atau tunggal"], ["Suasana hati rendah atau mudah tersinggung yang menetap", "Kehilangan minat, perubahan tidur/makan, atau sulit berkonsentrasi", "Merasa tidak berharga, putus asa, atau menarik diri"], "Depresi dapat memengaruhi sekolah, relasi, kesehatan, dan rasa aman. Ini bukan kesalahan atau kelemahan seseorang dan ada dukungan profesional yang dapat dicari.", ["Bangun dukungan sosial dan rutinitas yang memungkinkan", "Bicarakan perubahan yang dirasakan dengan orang dewasa aman", "Hindari memberi label diagnosis kepada diri sendiri atau teman"], ["Ceritakan perubahan kepada orang tepercaya", "Minta bantuan profesional kesehatan jiwa untuk penilaian", "Jika ada pikiran menyakiti diri, jangan sendirian dan cari bantuan segera"], "Cari bantuan profesional bila tanda menetap, mengganggu keseharian, atau menimbulkan putus asa. Dalam krisis, hubungi Healing119.id/119 ekstensi 8 atau layanan darurat setempat; layanan Healing119 beroperasi dari pagi hingga malam, bukan jaminan 24 jam.", [["Apakah stres sama dengan depresi?", "Tidak. Stres merupakan respons terhadap tekanan; depresi adalah kondisi kesehatan mental yang perlu dinilai profesional."], ["Apakah perubahan mood cukup untuk mendiagnosis depresi?", "Tidak. Diagnosis tidak dapat ditentukan dari satu gejala atau kuis daring."], ["Apa yang harus dilakukan jika teman berkata ingin menyakiti diri?", "Dengarkan tanpa menghakimi, tetap bersama atau hubungi orang dewasa aman, dan cari bantuan profesional/krisis segera."]], [whoMental, healing]),
];

export const safetyTopics: Topic[] = [
  topic("perundungan-fisik", "Perundungan fisik", "Mengenali tindakan fisik yang berulang atau mengintimidasi dan memilih langkah aman.", "Perundungan fisik dapat berupa memukul, menendang, mendorong, merusak barang, atau tindakan fisik lain yang menyakiti atau menakut-nakuti. Tanggung jawab berada pada pelaku dan orang dewasa yang perlu menjaga keselamatan.", ["Ketimpangan kuasa atau dukungan kelompok pada pelaku", "Lingkungan yang menormalkan kekerasan", "Tidak adanya respons aman dari orang dewasa"], ["Luka, barang rusak, atau ketakutan pada tempat/waktu tertentu", "Menghindari kelas, kegiatan, atau teman tertentu", "Ancaman atau tindakan yang berulang"], "Korban dapat merasa tidak aman, cemas, sulit belajar, atau menarik diri. Dampak setiap orang berbeda dan bukan kesalahan korban.", ["Sampaikan pola perundungan kepada guru/orang dewasa aman", "Sekolah perlu membangun lingkungan yang menghentikan kekerasan", "Teman dapat menemani korban menuju orang dewasa tanpa memaksa"], ["Pergi ke tempat ramai atau ruang yang diawasi bila memungkinkan", "Jangan membalas atau menghadapi pelaku sendirian bila berisiko", "Minta bantuan orang dewasa dan layanan kesehatan bila terluka"], "Cari bantuan orang dewasa tepercaya atau pengelola sekolah. Jika ada cedera serius atau bahaya langsung, hubungi layanan darurat; kekerasan terhadap anak dapat dilaporkan ke SAPA 129.", [["Apa yang dilakukan jika dipukul di sekolah?", "Menjauh ke tempat aman, beri tahu orang dewasa tepercaya, dan minta pemeriksaan kesehatan bila terluka."], ["Haruskah korban menghadapi pelaku?", "Tidak jika situasi berisiko. Keselamatan lebih utama; minta orang dewasa terlatih menangani situasi."], ["Bagaimana menemani teman korban?", "Dengarkan, yakinkan bahwa itu bukan salahnya, dan tawarkan menemani mencari bantuan."]], [unicefCyber, sapa, polri110]),
  topic("perundungan-verbal", "Perundungan verbal", "Mengenali ejekan, hinaan, ancaman, atau ucapan merendahkan yang berulang.", "Perundungan verbal menggunakan kata-kata untuk mengintimidasi, mempermalukan, atau merendahkan seseorang. Candaan yang menyakiti tetap perlu dihentikan ketika seseorang merasa terancam atau dipermalukan.", ["Norma kelompok yang menganggap penghinaan sebagai candaan", "Ketimpangan kuasa atau pengulangan oleh beberapa orang", "Diskriminasi terhadap identitas atau kondisi seseorang"], ["Julukan merendahkan atau hinaan yang berulang", "Ancaman, pelecehan, atau komentar tentang tubuh dan identitas", "Korban tampak takut bicara atau menghindari kelompok tertentu"], "Ucapan merendahkan dapat memengaruhi rasa percaya diri, suasana hati, dan rasa aman. Tidak terlihat luka fisik bukan berarti dampaknya tidak nyata.", ["Tetapkan aturan komunikasi yang menghormati orang lain", "Sampaikan kepada orang dewasa yang mampu menindaklanjuti", "Jangan ikut menyebarkan ucapan atau konten yang merendahkan"], ["Jika aman, katakan singkat bahwa ucapan itu tidak nyaman lalu menjauh", "Simpan bukti bila ancaman dilakukan secara tertulis", "Cari dukungan teman dan orang dewasa tepercaya"], "Minta bantuan guru, konselor, keluarga aman, atau SAPA 129 bila ada ancaman atau kekerasan terhadap anak.", [["Apakah bercanda yang menyakiti termasuk bullying?", "Bila tindakan berulang, mempermalukan, mengintimidasi, atau membuat seseorang tidak aman, jangan dianggap candaan biasa."], ["Bagaimana jika pelaku bilang hanya bercanda?", "Dampak dan batas orang yang menerima tetap penting. Sampaikan kepada orang dewasa yang dipercaya."], ["Apa yang dilakukan jika mendapat ancaman?", "Jangan menghadapi sendiri; cari tempat aman, simpan bukti bila aman, dan beri tahu orang dewasa tepercaya."]], [unicefCyber, sapa, polri110]),
  topic("perundungan-sosial", "Perundungan sosial", "Mengenali pengucilan, rumor, atau manipulasi hubungan yang membuat seseorang merasa tidak aman.", "Perundungan sosial berupaya merusak hubungan atau reputasi, misalnya mengucilkan secara sengaja, menyebarkan rumor, atau mengajak orang lain menjauhi seseorang.", ["Tekanan kelompok dan ketimpangan posisi sosial", "Penyebaran rumor tanpa memeriksa dampak", "Konflik yang berkembang menjadi pengucilan berulang"], ["Dijauhkan dari kegiatan atau kelompok secara terus-menerus", "Rumor atau rahasia pribadi disebarkan", "Teman lain ditekan agar tidak berinteraksi"], "Pengucilan dapat membuat korban kesepian, cemas, dan sulit merasa aman di sekolah atau komunitas. Korban tidak bertanggung jawab atas pilihan pelaku.", ["Jangan menyebarkan rumor atau ikut mengucilkan", "Beri ruang berteman tanpa tekanan kelompok", "Laporkan pola pengucilan kepada guru/orang dewasa aman"], ["Cari teman atau orang dewasa yang bisa menemani", "Simpan bukti pesan bila pengucilan dilakukan secara daring", "Jangan memaksa korban membuka cerita di depan kelompok"], "Hubungi guru, konselor, atau orang dewasa tepercaya. Jika pengucilan disertai ancaman atau kekerasan, cari bantuan perlindungan.", [["Apakah tidak diajak sekali berarti bullying?", "Belum tentu. Pola, kesengajaan, dampak, dan ketimpangan kuasa perlu dipertimbangkan oleh orang dewasa yang menangani."], ["Bagaimana membantu teman yang dikucilkan?", "Sapa dan dengarkan tanpa memaksa. Ajak kegiatan yang terasa aman dan bantu menghubungi orang dewasa."], ["Haruskah rumor dibantah di media sosial?", "Pertimbangkan risiko. Simpan bukti dan minta dukungan orang dewasa sebelum merespons secara terbuka."]], [unicefCyber, sapa, polri110]),
  topic("cyberbullying", "Cyberbullying", "Langkah aman menghadapi perundungan digital dan mencari bantuan.", "Cyberbullying adalah perundungan melalui teknologi digital, seperti pesan, unggahan, komentar, atau penyebaran konten untuk menyakiti atau mempermalukan seseorang.", ["Penyebaran konten yang cepat dan sulit dikendalikan", "Akun anonim atau tekanan kelompok", "Kurangnya dukungan saat korban melaporkan"], ["Pesan, komentar, atau unggahan yang merendahkan berulang", "Akun palsu, ancaman, atau penyebaran tangkapan layar pribadi", "Takut membuka aplikasi atau mengalami gangguan tidur dan suasana hati"], "Dampaknya dapat terasa di rumah maupun sekolah, termasuk malu, marah, cemas, atau menarik diri. Simpan bukti dengan aman dan jangan menyebarkannya.", ["Atur privasi akun dan batasi informasi lokasi/pribadi", "Gunakan fitur blokir dan laporkan konten pada platform", "Bangun kesepakatan kelas/keluarga untuk tidak ikut menyebarkan konten"], ["Beri tahu orang dewasa yang dipercaya", "Simpan tangkapan layar/tautan sebagai bukti tanpa meneruskannya", "Blokir dan laporkan akun; jangan membalas jika dapat meningkatkan risiko"], "Untuk ancaman, eksploitasi, kekerasan seksual, atau keselamatan anak, cari bantuan orang dewasa dan SAPA 129. Bahaya langsung membutuhkan layanan darurat.", [["Apa saja contoh cyberbullying?", "Pesan/komentar yang merendahkan secara berulang, akun palsu untuk mengintimidasi, atau menyebarkan konten untuk mempermalukan."], ["Apa yang harus dilakukan jika takut melapor?", "Mulai dengan satu orang dewasa yang terasa aman dan minta ditemani. Kamu tidak perlu menghadapinya sendiri."], ["Bagaimana membantu teman yang dibully online?", "Dengarkan tanpa menyalahkan, jangan sebarkan konten, dan tawarkan menemani menyimpan bukti serta mencari bantuan."]], [unicefCyber, sapa, polri110]),
  topic("kekerasan-fisik", "Kekerasan fisik", "Mengutamakan keselamatan dan mendapatkan pertolongan setelah tindakan yang melukai atau mengancam.", "Kekerasan fisik adalah tindakan yang menggunakan tenaga atau benda untuk melukai, menakut-nakuti, atau mengendalikan seseorang. Tidak ada korban yang pantas menerima kekerasan.", ["Paksaan atau kontrol dalam keluarga, relasi, sekolah, atau lingkungan", "Situasi yang meningkat tanpa dukungan keselamatan", "Ketergantungan korban kepada pelaku dapat menyulitkan pencarian bantuan"], ["Luka, nyeri, atau tanda fisik yang tidak dapat dijelaskan", "Ketakutan terhadap seseorang atau tempat tertentu", "Ancaman, pemukulan, penahanan, atau penggunaan benda untuk melukai"], "Selain cedera, korban dapat mengalami rasa takut, sulit tidur, dan gangguan keseharian. Dampak tidak selalu tampak dari luar.", ["Kenali orang dan tempat yang dapat membantu", "Susun langkah keselamatan bersama orang tepercaya jika ada risiko berulang", "Jangan menyalahkan atau memaksa korban mengambil keputusan tertentu"], ["Jika bahaya sedang terjadi, menjauh ke lokasi aman bila memungkinkan", "Hubungi orang dewasa tepercaya atau layanan darurat", "Cari pertolongan medis untuk cedera dan pendampingan perlindungan"], "SAPA 129 menerima laporan kekerasan terhadap perempuan dan anak. Jika ada bahaya langsung, hubungi polisi 110 atau layanan darurat setempat; jangan menghadapi pelaku sendirian.", [["Apa yang dilakukan jika masih tinggal dengan pelaku?", "Jangan menantang pelaku sendirian. Cari pendamping dewasa atau layanan perlindungan untuk menyusun langkah keselamatan."], ["Apakah luka ringan tetap perlu bantuan?", "Jika kamu khawatir atau merasa tidak aman, bicarakan dengan tenaga kesehatan atau orang dewasa tepercaya."], ["Siapa dapat dihubungi?", "Untuk kekerasan terhadap anak/perempuan, SAPA 129 menyediakan telepon 129 dan WhatsApp resmi 08111-129-129."]], [sapa, polri110]),
  topic("kekerasan-verbal", "Kekerasan verbal", "Mengenali penghinaan, ancaman, atau ucapan yang digunakan untuk menakut-nakuti dan mengendalikan.", "Kekerasan verbal menggunakan kata-kata untuk merendahkan, mengancam, atau mengendalikan. Pola perilaku dan rasa aman perlu diperhatikan, bukan hanya apakah pelaku menyebutnya bercanda.", ["Pola kontrol dan ketimpangan kuasa", "Konflik yang berulang tanpa dukungan", "Ucapan diskriminatif atau ancaman yang dinormalisasi"], ["Ancaman untuk melukai, mengusir, atau mempermalukan", "Hinaan berulang yang menyerang harga diri", "Korban merasa takut berbicara atau melakukan kesalahan kecil"], "Ucapan mengancam dapat membuat korban takut, terisolasi, dan kehilangan rasa aman. Dampak emosional layak mendapat perhatian dan dukungan.", ["Cari dukungan di luar situasi yang mengancam", "Jangan ikut menormalisasi hinaan sebagai candaan", "Buat rencana aman dengan orang dewasa tepercaya"], ["Menjauh jika percakapan meningkat dan situasi memungkinkan", "Catat ancaman secara aman hanya jika tidak menambah risiko", "Bicarakan dengan konselor atau layanan perlindungan"], "Jika ucapan disertai ancaman atau kontrol, hubungi orang dewasa aman. Kekerasan terhadap anak/perempuan dapat disampaikan ke SAPA 129.", [["Apakah bentakan sekali sama dengan kekerasan verbal?", "Konteks dan pola penting. Ancaman, penghinaan, atau tindakan berulang perlu ditanggapi serius dan dibicarakan dengan pihak aman."], ["Bagaimana bila pelaku adalah keluarga?", "Kamu tetap berhak mendapat bantuan. Cari orang dewasa tepercaya di luar situasi tersebut."], ["Apa yang dilakukan jika ancaman semakin berat?", "Pergi ke tempat aman dan hubungi layanan darurat atau pendamping perlindungan."]], [sapa, whoMental, polri110]),
  topic("kekerasan-seksual", "Kekerasan seksual", "Informasi yang berpihak pada keselamatan korban, tanpa menyalahkan atau memaksa bercerita.", "Kekerasan seksual adalah tindakan seksual yang tidak diinginkan, dilakukan melalui paksaan, manipulasi, ancaman, atau tanpa persetujuan yang bebas. Tanggung jawab ada pada pelaku, bukan korban.", ["Penyalahgunaan kuasa, kepercayaan, atau ketergantungan", "Tekanan, ancaman, manipulasi, atau situasi ketika korban tidak dapat menyetujui", "Paparan daring dan penyebaran konten tanpa persetujuan"], ["Sentuhan atau ajakan seksual yang tidak diinginkan", "Dipaksa, diancam, atau dimanipulasi untuk melakukan sesuatu", "Konten pribadi diambil, disimpan, atau disebarkan tanpa persetujuan"], "Korban dapat mengalami dampak fisik, emosional, sosial, dan rasa aman. Respons tiap orang berbeda; korban tidak perlu membuktikan bahwa dirinya cukup terluka untuk meminta bantuan.", ["Pelajari batas dan hak atas tubuh", "Dukung akses ke orang dewasa dan petugas yang dapat dipercaya", "Jaga privasi korban dan jangan menyebarkan cerita atau bukti"], ["Pindah ke tempat aman; jangan menghadapi pelaku sendiri", "Hubungi orang dewasa tepercaya dan layanan perlindungan", "Cari bantuan kesehatan segera bila diperlukan; profesional dapat menjelaskan pilihan selanjutnya"], "SAPA 129 adalah kanal resmi untuk kekerasan terhadap perempuan dan anak. Jika ada bahaya langsung, hubungi polisi 110. Jangan paksa korban melapor atau menceritakan detail berulang kali.", [["Apakah korban bersalah karena tidak melawan?", "Tidak. Respons saat mengalami ancaman berbeda-beda. Tanggung jawab kekerasan ada pada pelaku."], ["Bagaimana membantu teman yang bercerita?", "Dengarkan, percaya bahwa ia membutuhkan dukungan, hindari pertanyaan menyalahkan, dan tawarkan menemani mencari bantuan."], ["Ke mana mencari bantuan?", "Kekerasan terhadap perempuan/anak dapat dilaporkan ke SAPA 129 melalui 129 atau WhatsApp 08111-129-129."]], [sapa, kemenkesRepro, polri110]),
  topic("kekerasan-emosional", "Kekerasan emosional", "Mengenali pola intimidasi, penghinaan, ancaman, dan kontrol yang memengaruhi rasa aman.", "Kekerasan emosional dapat berbentuk tindakan berulang untuk menakut-nakuti, merendahkan, mengisolasi, atau mengendalikan seseorang. Satu halaman ini bukan alat diagnosis hubungan.", ["Ketimpangan kuasa dan ketergantungan", "Isolasi dari teman/keluarga", "Perilaku kontrol yang dianggap wajar oleh lingkungan"], ["Diancam, dipermalukan, atau terus disalahkan", "Dilarang bertemu orang yang dipercaya atau dipantau berlebihan", "Merasa takut menentukan pilihan atau menyampaikan pendapat"], "Perlakuan semacam ini dapat mengikis rasa percaya diri dan membuat korban sulit meminta bantuan. Korban berhak mendapat dukungan tanpa paksaan.", ["Jaga koneksi dengan orang yang aman", "Kenali tanda kontrol dan batas yang penting bagimu", "Minta bantuan pihak yang memahami perlindungan dan keselamatan"], ["Ceritakan kepada orang tepercaya di luar relasi jika aman", "Jangan konfrontasi pelaku sendirian apabila dapat meningkatkan bahaya", "Cari layanan pendampingan untuk menyusun langkah yang aman"], "Jika kamu atau teman mengalami ancaman atau kontrol yang membahayakan, hubungi orang dewasa tepercaya atau SAPA 129 untuk kasus anak/perempuan.", [["Bagaimana membedakan konflik dan kekerasan emosional?", "Perhatikan pola kontrol, ancaman, penghinaan, ketakutan, dan ketimpangan kuasa. Pihak profesional dapat membantu menilai situasi."], ["Apakah saya harus memutus relasi segera?", "Keputusan dan keselamatan harus dipertimbangkan dengan pendamping aman. Jangan mengambil langkah yang berisiko tanpa dukungan."], ["Bagaimana membantu teman?", "Percaya dan dengarkan, jangan memaksa keputusan, dan bantu mencari pendamping yang aman."]], [sapa, whoMental, polri110]),
  topic("kekerasan-dalam-hubungan", "Kekerasan dalam hubungan", "Mengenali kontrol dan paksaan dalam relasi serta memprioritaskan keselamatan.", "Kekerasan dalam hubungan dapat berupa fisik, seksual, verbal, emosional, atau kontrol digital. Hubungan dekat tidak membuat seseorang berhak mengancam atau mengendalikan pasangannya.", ["Cemburu yang digunakan untuk membatasi atau mengontrol", "Tekanan, ancaman, atau ketergantungan", "Isolasi dan pemantauan digital"], ["Pasangan mengatur pakaian, pertemanan, atau lokasi secara memaksa", "Ancaman, penghinaan, pemaksaan, atau kekerasan fisik", "Takut mengatakan tidak atau mengakhiri hubungan"], "Kekerasan dapat membuat seseorang merasa terjebak dan terisolasi. Hubungan yang sehat menghormati batas, pilihan, dan rasa aman.", ["Jaga hubungan dengan teman/orang dewasa aman", "Lindungi akun dan lokasi digital jika ada pemantauan", "Rencanakan langkah dengan pendamping bila ingin menjauh"], ["Hindari putus atau konfrontasi tatap muka sendirian bila berisiko", "Simpan bukti dengan aman bila tidak membahayakan", "Cari bantuan pendampingan dan tempat aman"], "Untuk korban anak/perempuan, SAPA 129 dapat memberi jalur laporan dan pendampingan. Bahaya langsung memerlukan bantuan darurat.", [["Apakah berbagi kata sandi bukti cinta?", "Tidak. Kamu berhak menjaga privasi dan batas digital. Tekanan untuk memberi akses akun dapat menjadi tanda kontrol."], ["Bagaimana jika saya takut mengakhiri hubungan?", "Jangan lakukan sendirian bila khawatir akan bahaya. Diskusikan rencana keselamatan dengan orang dewasa atau pendamping tepercaya."], ["Apakah ancaman melalui chat perlu disimpan?", "Simpan hanya jika aman, jangan sebarkan, dan minta bantuan orang dewasa untuk menentukan langkah berikutnya."]], [sapa, unicefCyber, polri110]),
  topic("perlindungan-anak-remaja", "Perlindungan anak dan remaja", "Mengetahui siapa yang dapat membantu saat hak, keselamatan, atau batas diri terancam.", "Perlindungan anak mencakup upaya mencegah dan menanggapi kekerasan, eksploitasi, penelantaran, dan perlakuan yang membahayakan. Remaja berhak didengar dan mendapat dukungan yang mengutamakan keselamatan.", ["Kekerasan atau eksploitasi di rumah, sekolah, komunitas, maupun daring", "Hambatan untuk bercerita atau akses bantuan", "Ketergantungan pada orang yang dapat menjadi sumber ancaman"], ["Takut pulang atau bertemu seseorang", "Luka, ancaman, pemaksaan, atau permintaan rahasia yang membuat tidak nyaman", "Isolasi dari teman, sekolah, atau akses komunikasi"], "Dampak perlindungan yang tidak memadai dapat menyentuh kesehatan, pendidikan, rasa aman, dan hubungan sosial. Keselamatan korban adalah prioritas.", ["Kenali orang dewasa yang dapat dipercaya", "Sekolah, keluarga, layanan sosial, dan tenaga kesehatan dapat menjadi bagian dukungan", "Jaga informasi pribadi dan bukti tanpa menyebarkannya"], ["Jika aman, pindah ke tempat ramai dan hubungi orang dewasa tepercaya", "Jangan setujui pertemuan atau konfrontasi dengan orang yang mengancam", "Hubungi SAPA 129 untuk kekerasan terhadap anak/perempuan"], "SAPA 129 dapat dihubungi melalui telepon 129 dan WhatsApp 08111-129-129. Bahaya langsung: polisi 110 atau layanan darurat setempat. SIRAMA bukan kanal pelaporan resmi.", [["Apakah harus punya bukti sebelum meminta bantuan?", "Kamu tetap boleh meminta bantuan saat merasa tidak aman. Petugas berwenang dapat menjelaskan informasi yang dibutuhkan."], ["Bagaimana jika orang dewasa pertama tidak percaya?", "Coba sampaikan kepada orang dewasa aman lainnya, seperti guru, kerabat, tenaga kesehatan, atau layanan perlindungan."], ["Apa yang bisa dilakukan teman?", "Dengarkan, jangan menyebarkan cerita, dan bantu menghubungkan ke orang dewasa tepercaya atau layanan resmi."]], [sapa, unicefCyber, polri110]),
];

export const educationArticles = [
  { slug: "persiapan-melanjutkan-pendidikan", title: "Menyiapkan langkah setelah lulus", summary: "Menyusun pilihan pendidikan, kebutuhan, dan jadwal secara bertahap.", content: ["Mulai dengan mengenali minat, cara belajar, biaya, lokasi, dan dukungan yang tersedia. Bicarakan pilihan dengan guru BK, keluarga yang aman, atau alumni.", "Catat persyaratan dan tanggal dari situs resmi setiap perguruan tinggi. Buat daftar dokumen dan pengingat, tetapi hindari membagikan kata sandi atau identitas kepada pihak yang tidak jelas.", "Jika ada hambatan biaya, periksa bantuan resmi seperti KIP Kuliah dan informasi kampus. Ketentuan dapat berubah setiap tahun."], sources: [kip], faqs: [["Kapan sebaiknya mulai menyiapkan pilihan setelah lulus?", "Mulai bertahap dengan mencari informasi jenjang, biaya, minat, dan jadwal resmi. Guru BK atau orang dewasa tepercaya dapat membantu membandingkan pilihan."], ["Bagaimana jika biaya menjadi kendala?", "Periksa bantuan pendidikan pada situs resmi pemerintah/kampus dan pastikan syarat serta periode masih berlaku."]] },
  { slug: "keterampilan-remaja", title: "Mengembangkan keterampilan yang relevan", summary: "Belajar melalui proyek kecil, kegiatan sekolah, dan sumber pembelajaran yang dapat diperiksa.", content: ["Pilih satu keterampilan yang ingin dicoba, lalu buat target yang terukur dan realistis. Proyek sederhana membantu melihat minat sekaligus menghasilkan bukti belajar.", "Manfaatkan perpustakaan, pelatihan sekolah, atau kursus dengan penyelenggara yang jelas. Periksa biaya, syarat, keamanan, dan kebijakan privasi sebelum mendaftar.", "Keterampilan berkembang lewat latihan dan umpan balik. Tidak perlu membeli kursus atau alat mahal untuk mulai belajar."], sources: [kemendikdasmenBk, kemendikdasmenTalent], faqs: [["Keterampilan apa yang perlu saya pelajari?", "Mulai dari hal yang ingin dicoba dan kebutuhan belajar atau kegiatanmu. Tidak ada satu daftar yang wajib untuk semua orang."], ["Apakah harus membeli kursus berbayar?", "Tidak. Kamu bisa mulai lewat proyek sederhana, perpustakaan, kegiatan sekolah, atau sumber belajar gratis yang penyelenggaranya jelas."]] },
  { slug: "perencanaan-karier", title: "Mengenal pilihan karier", summary: "Menghubungkan minat, pengalaman, dan informasi pekerjaan tanpa harus menentukan semuanya sekarang.", content: ["Pilihan karier bisa berubah seiring pengalaman. Mulai dari mata pelajaran, kegiatan, dan masalah yang menarik perhatianmu.", "Cari informasi tugas, jalur pendidikan, keterampilan, dan kondisi kerja melalui sumber institusi atau organisasi profesi yang relevan.", "Diskusikan keputusan dengan guru BK atau orang dewasa tepercaya. Beri ruang untuk mengeksplorasi dan mengubah arah."], sources: [kemendikdasmenBk, kemendikdasmenTalent], faqs: [["Apakah saya harus menentukan karier sekarang?", "Tidak. Kamu dapat mengeksplorasi minat dan informasi, lalu meninjau pilihan seiring pengalaman dan tahap pendidikan."], ["Siapa yang bisa membantu merencanakan karier?", "Guru BK, keluarga yang aman, alumni, dan sumber resmi pendidikan dapat membantu menjelaskan pilihan tanpa memaksa satu keputusan."]] },
  { slug: "potensi-diri", title: "Mengenali dan mengembangkan potensi diri", summary: "Membangun ruang untuk mencoba, berlatih, dan mengevaluasi tanpa membandingkan perjalananmu.", content: ["Potensi tidak selalu terlihat sebagai prestasi akademik. Minat, kepedulian, kreativitas, ketekunan, dan kemampuan bekerja bersama juga dapat dikembangkan.", "Cobalah kegiatan yang tersedia di sekolah atau komunitas. Tetapkan langkah kecil dan evaluasi apa yang terasa menarik atau perlu dukungan.", "Jaga waktu istirahat dan jangan merasa harus unggul di semua hal. Minta umpan balik yang spesifik dan menghargai."], sources: [kemendikdasmenBk, kemendikdasmenTalent], faqs: [["Bagaimana jika saya belum tahu potensi saya?", "Tidak apa-apa. Coba kegiatan baru secara bertahap, perhatikan hal yang membuatmu tertarik, dan mintalah umpan balik yang membangun."], ["Apakah potensi harus selalu berupa prestasi akademik?", "Tidak. Minat, kepedulian, kreativitas, ketekunan, dan kemampuan bekerja sama juga dapat menjadi kekuatan yang berkembang."]] },
  { slug: "memeriksa-informasi-program", title: "Cara memeriksa informasi pendidikan", summary: "Mengenali penyelenggara, syarat, manfaat, jadwal, dan kanal resmi sebelum bertindak.", content: ["Mulailah dari situs resmi penyelenggara. Pastikan alamat dan nama program benar, lalu cocokkan informasi ringkasan dengan pengumuman terbaru.", "Periksa jenjang, persyaratan, cara seleksi, manfaat, periode pendaftaran, dan dokumen yang diperlukan. Jangan menganggap ringkasan lama masih berlaku.", "Waspadai biaya atau permintaan kata sandi yang tidak dijelaskan penyelenggara. Jika ragu, hubungi kanal resmi yang tercantum di situsnya."], sources: [kip], faqs: [["Bagaimana memastikan beasiswa masih dibuka?", "Periksa tanggal terbaru di situs resmi penyelenggara. Jangan mengandalkan poster atau ringkasan lama."], ["Apakah SIRAMA meminta data untuk pendaftaran?", "Tidak. Proses pendaftaran hanya dilakukan melalui kanal resmi penyelenggara; SIRAMA tidak meminta dokumen atau kata sandi."]] },
];

